templates.body:
anthropic-api-key: {{api_key}}
set-env:
  - "ANTHROPIC_API_BASE={{{base_url}}}"
model: {{concat "anthropic/" model_alias}}
weak-model: {{concat "anthropic/" model_slot_fast}}
analytics-disable: true
check-update: false
show-release-notes: false

companions.body:
{{#unless forward_auth}}{
{{#unless (eq model_slot_fast model_alias)}}  "{{concat "anthropic/" model_slot_fast}}": { "litellm_provider": "anthropic", "mode": "chat" },
{{/unless}}  "{{concat "anthropic/" model_alias}}": { "litellm_provider": "anthropic", "mode": "chat"{{#if context_window}}, "max_input_tokens": {{context_window}}{{/if}}{{#if max_output_tokens}}, "max_output_tokens": {{max_output_tokens}}{{/if}} }
}
{{/unless}}

templates.body:
export ANTHROPIC_API_BASE={{base_url}}
export ANTHROPIC_API_KEY={{api_key}}
export AIDER_MODEL={{concat "anthropic/" model_alias}}
export AIDER_WEAK_MODEL={{concat "anthropic/" model_slot_fast}}
export AIDER_ANALYTICS_DISABLE=true
export AIDER_CHECK_UPDATE=false
export AIDER_SHOW_RELEASE_NOTES=false

openai-api-base: {{base_url}}
openai-api-key: {{api_key}}
model: {{concat "openai/" model_alias}}
weak-model: {{concat "openai/" model_slot_fast}}
analytics-disable: true
check-update: false
show-release-notes: false

companions.body:
{{#unless forward_auth}}{
{{#unless (eq model_slot_fast model_alias)}}  "{{concat "openai/" model_slot_fast}}": { "litellm_provider": "openai", "mode": "chat" },
{{/unless}}  "{{concat "openai/" model_alias}}": { "litellm_provider": "openai", "mode": "chat"{{#if context_window}}, "max_input_tokens": {{context_window}}{{/if}}{{#if max_output_tokens}}, "max_output_tokens": {{max_output_tokens}}{{/if}} }
}
{{/unless}}
